class Member:
    pass

# member0 is a Member
member0 = Member()

# While in the block, member is a local variable that is the Member whose id is "member0",
# and if there is a member, then the member's role is "ADMIN"
{
    member = Member["member0"]
    if member:
        member.role = "ADMIN"
}

assert(member0.role, "ADMIN")

